// Downloadable CV templates (public/templates/*.docx, generated by
// scripts/generate-cv-templates.mjs). The /cv-templates page, the sitemap, the
// llms files and the parser test all read this list.
// Copy rules: no em dashes, no "X, not Y" phrasing, no invented statistics.
import type { AppLocale } from '@/i18n/routing'
import type { FastAtsSectionKey } from '@/lib/ats-fast-parser'

